    if op.num_results:
        names = [self._name_state.get_value_name(r) for r in op.results]
        pieces.append(", ".join(names) + " =")
    pieces.append(op.name)

    callee = op.attributes.get("callee")
    if isinstance(callee, FlatSymbolRefAttr):
        pieces.append(f"@{callee.value}")
    elif op.attributes.get("sym_name") is not None and not op.regions:
        pieces.append(f"@{op.attributes['sym_name'].value}")

    if op.name in _KEYWORD_FIRST_OPS:
        predicate = op.attributes.get("predicate")
        if predicate is not None:
            separator = "," if op.name.startswith("arith.") else ""
            pieces.append(f"{predicate.value}{separator}")
    keywords = op.attributes.get("assembly_keywords")

    value_attr = op.attributes.get("value")
    if value_attr is not None and not op.num_operands:
        pieces.append(self._format_value_attribute(value_attr))

